import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { normaliseName } from '../names.js';
test('examples', () => {
  assert.equal(normaliseName('  john  SMITH '), 'John Smith');
  assert.equal(normaliseName('SMITH, jane'), 'Jane Smith');
  assert.equal(normaliseName("mary-jane o'brien"), "Mary-Jane O'Brien");
});
test('more of the same', () => {
  assert.equal(normaliseName('ANNE MARIE  WONG'), 'Anne Marie Wong');
  assert.equal(normaliseName('JONES,  SAM'), 'Sam Jones');
  assert.equal(normaliseName('li,WEI'), 'Wei Li');
  assert.equal(normaliseName('cher'), 'Cher');
  assert.equal(normaliseName("D'ANGELO, carla-rose"), "Carla-Rose D'Angelo");
});
test('file was rewritten', () => {
  assert.equal(readFileSync(new URL('../data/people.txt', import.meta.url), 'utf8'), "John Smith\nJane Smith\nMary-Jane O'Brien\nAnne Marie Wong\nSam Jones\nWei Li\n");
});

solution.names.js:
const cap = (w) => w.split(/([-'])/).map((p) => (p === '-' || p === "'" ? p : p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())).join('');

export function normaliseName(raw) {
  let s = String(raw).trim().replace(/\s+/g, ' ');
  if (s.includes(',')) {
    const [last, first] = s.split(',').map((x) => x.trim());
    s = (first + ' ' + last).trim();
  }
  return s.split(' ').filter(Boolean).map(cap).join(' ');
}

